// Apply appearance before the first paint, including in the desktop CSP.
(()=>{let theme='system',scale=1,dark=matchMedia('(prefers-color-scheme: dark)').matches;try{const settings=JSON.parse(localStorage.getItem('circuit-lab-experiments-v2'))?.settings;theme=settings?.theme??'system';if(Number.isFinite(settings?.uiScale))scale=Math.round(Math.max(.75,Math.min(2,settings.uiScale))*100)/100;}catch{}try{if(typeof globalThis.CircuitSystemTheme?.isDark==='function'){dark=CircuitSystemTheme.isDark();globalThis.circuitLabNativeDark=dark;}}catch{}document.documentElement.style.setProperty('--ui-scale',scale);document.documentElement.classList.toggle('ui-compact-settings',innerWidth/scale<360);document.documentElement.dataset.theme=theme==='dark'||theme!=='light'&&dark?'dark':'light';})();
